const{TableMap:TableMap,CellSelection:CellSelection,selectedRect:selectedRect}=TiptapPMTables;function getColumnCellPositions(e,t){const l=[];for(let o=0;o<e.width;o++){l.push(t+e.map[o])}return l}function getRowCellPositions(e,t){const l=[];for(let o=0;o<e.height;o++){l.push(t+e.map[o*e.width])}return l}function cellSelectionInfo(e){const t=e.selection;if(!(t instanceof CellSelection)){return null}const l=selectedRect(e);return{tableStart:l.tableStart,left:l.left,right:l.right,top:l.top,bottom:l.bottom,isCol:t.isColSelection(),isRow:t.isRowSelection()}}export{TableMap,getColumnCellPositions,getRowCellPositions,cellSelectionInfo};